//! Read-only Windows spelling of stored page text. No user dictionary writes.
use serde::Serialize;
pub const MAX_UNITS:usize=50000;
#[derive(Debug,Serialize)]pub struct Finding{pub word:String,pub start:usize,pub length:usize,pub action:u32,pub replacement:String,pub suggestions:Vec<String>,pub context:String}
#[derive(Debug,Serialize)]pub struct Report{pub language:String,pub source:String,pub text_units:usize,pub total:usize,pub truncated:bool,pub findings:Vec<Finding>}
fn language(value:&str)->Result<(),String>{if value.is_empty()||value.len()>64||!value.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'){Err("Choose a supported BCP47 spelling language".into())}else{Ok(())}}
fn evidence(text:&[u16],start:usize,length:usize)->Result<(String,String),String>{let end=start.checked_add(length).ok_or("Invalid spelling range")?;if length==0||end>text.len(){return Err("Invalid spelling range".into())}let word=String::from_utf16(&text[start..end]).map_err(|_|"Spelling range splits a Unicode character")?;let mut left=start.saturating_sub(35);let mut right=(end+35).min(text.len());if left>0&&(0xdc00..=0xdfff).contains(&text[left]){left-=1}if right<text.len()&&(0xd800..=0xdbff).contains(&text[right-1]){right+=1}Ok((word,String::from_utf16_lossy(&text[left..right])))}
pub fn source(db:&str,url:&str)->crate::Result<String>{let html=crate::load_source(db,url)?.ok_or("No recorded HTTP source for this URL")?;if html.len()>2*1024*1024{return Err("Spelling HTML source exceeds 2 MiB".into())}let mut document=scraper::Html::parse_document(&html);let controls:Vec<_>=document.select(&scraper::Selector::parse("textarea,select").unwrap()).map(|node|node.id()).collect();for id in controls{if let Some(mut node)=document.tree.get_mut(id){node.detach()}}let selector=scraper::Selector::parse("body").unwrap();Ok(document.select(&selector).next().map(|body|crate::extracted_text(body,true)).unwrap_or_default())}
pub fn languages()->Result<Vec<String>,String>{native::languages()}
pub fn check(text:&str,tag:&str)->Result<Report,String>{language(tag)?;if text.contains('\0'){return Err("Spelling text contains an embedded null".into())}let units=text.encode_utf16().count();if units>MAX_UNITS{return Err("Spelling text exceeds 50000 UTF-16 units; narrow the page content".into())}native::check(text,tag)}
#[cfg(not(windows))]mod native{pub fn languages()->Result<Vec<String>,String>{Err("Spelling requires Windows Spell Checking API".into())}pub fn check(_: &str,_:&str)->Result<super::Report,String>{Err("Spelling requires Windows Spell Checking API".into())}}
#[cfg(windows)]mod native{
 use super::*;use std::{ffi::c_void,ptr};type Raw=*mut c_void;type Hr=i32;
 #[repr(C)]struct Guid(u32,u16,u16,[u8;8]);
 #[repr(C)]struct Unknown{query:unsafe extern "system" fn(Raw,*const Guid,*mut Raw)->Hr,add:unsafe extern "system" fn(Raw)->u32,release:unsafe extern "system" fn(Raw)->u32}
 #[repr(C)]struct Factory{base:Unknown,languages:unsafe extern "system" fn(Raw,*mut Raw)->Hr,supported:unsafe extern "system" fn(Raw,*const u16,*mut i32)->Hr,create:unsafe extern "system" fn(Raw,*const u16,*mut Raw)->Hr}
 #[repr(C)]struct Checker{base:Unknown,tag:usize,check:unsafe extern "system" fn(Raw,*const u16,*mut Raw)->Hr,suggest:unsafe extern "system" fn(Raw,*const u16,*mut Raw)->Hr}
 #[repr(C)]struct Strings{base:Unknown,next:unsafe extern "system" fn(Raw,u32,*mut *mut u16,*mut u32)->Hr}
 #[repr(C)]struct Errors{base:Unknown,next:unsafe extern "system" fn(Raw,*mut Raw)->Hr}
 #[repr(C)]struct Error{base:Unknown,start:unsafe extern "system" fn(Raw,*mut u32)->Hr,length:unsafe extern "system" fn(Raw,*mut u32)->Hr,action:unsafe extern "system" fn(Raw,*mut u32)->Hr,replacement:unsafe extern "system" fn(Raw,*mut *mut u16)->Hr}
 #[link(name="Ole32")]extern "system"{fn CoInitializeEx(reserved:Raw,mode:u32)->Hr;fn CoUninitialize();fn CoCreateInstance(class:*const Guid,outer:Raw,context:u32,iid:*const Guid,result:*mut Raw)->Hr;fn CoTaskMemFree(memory:Raw);}
 struct Apartment(bool);impl Apartment{fn new()->Result<Self,String>{let hr=unsafe{CoInitializeEx(ptr::null_mut(),0)};if hr==0x80010106u32 as i32{Ok(Self(false))}else{ok(hr)?;Ok(Self(true))}}}impl Drop for Apartment{fn drop(&mut self){if self.0{unsafe{CoUninitialize()}}}}
 struct Com(Raw);impl Com{fn new(raw:Raw)->Result<Self,String>{if raw.is_null(){Err("Windows spelling returned no COM object".into())}else{Ok(Self(raw))}}unsafe fn table<T>(&self)->&T{&**(self.0 as *const *const T)}}impl Drop for Com{fn drop(&mut self){unsafe{(self.table::<Unknown>().release)(self.0);}}}
 fn ok(hr:Hr)->Result<(),String>{if hr<0{Err(format!("Windows spelling provider failed (HRESULT {:08X})",hr as u32))}else{Ok(())}}
 fn wide(value:&str)->Vec<u16>{value.encode_utf16().chain(Some(0)).collect()}
 fn factory()->Result<Com,String>{let class=Guid(0x7ab36653,0x1796,0x484b,[0xbd,0xfa,0xe7,0x4f,0x1d,0xb7,0xc1,0xdc]);let iid=Guid(0x8e018a9d,0x2415,0x4677,[0xbf,0x08,0x79,0x4e,0xa6,0x1f,0x94,0xbb]);let mut raw=ptr::null_mut();ok(unsafe{CoCreateInstance(&class,ptr::null_mut(),1,&iid,&mut raw)})?;Com::new(raw)}
 unsafe fn string(raw:*mut u16)->Result<String,String>{if raw.is_null(){return Ok(String::new())}struct Free(*mut u16);impl Drop for Free{fn drop(&mut self){unsafe{CoTaskMemFree(self.0.cast())}}}let _free=Free(raw);let mut len=0;while len<4096&&*raw.add(len)!=0{len+=1}if len==4096{return Err("Spelling provider string exceeds 4096 UTF-16 units".into())}String::from_utf16(std::slice::from_raw_parts(raw,len)).map_err(|_|"Invalid Unicode from spelling provider".into())}
 fn strings(object:Com,max:usize)->Result<Vec<String>,String>{let mut result=Vec::new();for _ in 0..max{let mut raw=ptr::null_mut();let mut fetched=0;let hr=unsafe{(object.table::<Strings>().next)(object.0,1,&mut raw,&mut fetched)};ok(hr)?;if fetched==0||hr==1{if !raw.is_null(){unsafe{CoTaskMemFree(raw.cast())}}break}result.push(unsafe{string(raw)}?)}Ok(result)}
 pub fn languages()->Result<Vec<String>,String>{let _apartment=Apartment::new()?;let factory=factory()?;let mut raw=ptr::null_mut();ok(unsafe{(factory.table::<Factory>().languages)(factory.0,&mut raw)})?;let mut languages=strings(Com::new(raw)?,256)?;languages.sort();languages.dedup();Ok(languages)}
 pub fn check(text:&str,tag:&str)->Result<Report,String>{let _apartment=Apartment::new()?;let factory=factory()?;let tag_wide=wide(tag);let mut supported=0;ok(unsafe{(factory.table::<Factory>().supported)(factory.0,tag_wide.as_ptr(),&mut supported)})?;if supported==0{return Err("Selected spelling language is not installed or supported by Windows".into())}let mut raw=ptr::null_mut();ok(unsafe{(factory.table::<Factory>().create)(factory.0,tag_wide.as_ptr(),&mut raw)})?;let checker=Com::new(raw)?;let wide=wide(text);let units=&wide[..wide.len()-1];let mut report=Report{language:tag.into(),source:"Recorded HTTP HTML; extracted content text; offsets in UTF-16 units".into(),text_units:units.len(),total:0,truncated:false,findings:vec![]};if text.trim().is_empty(){return Ok(report)}let start_time=std::time::Instant::now();let mut raw=ptr::null_mut();ok(unsafe{(checker.table::<Checker>().check)(checker.0,wide.as_ptr(),&mut raw)})?;let errors=Com::new(raw)?;let mut retained_bytes=0;
  loop{if start_time.elapsed()>std::time::Duration::from_secs(10){return Err("Spelling analysis exceeded its cooperative ten-second budget".into())}let mut raw=ptr::null_mut();let hr=unsafe{(errors.table::<Errors>().next)(errors.0,&mut raw)};ok(hr)?;if hr==1{break}let error=Com::new(raw)?;let(mut start,mut length,mut action)=(0,0,0);unsafe{let table=error.table::<Error>();ok((table.start)(error.0,&mut start))?;ok((table.length)(error.0,&mut length))?;ok((table.action)(error.0,&mut action))?;}let(word,context)=evidence(units,start as usize,length as usize)?;report.total+=1;if report.total>50000{return Err("Spelling provider returned an excessive number of errors".into())}if report.findings.len()>=200{report.truncated=true;continue}let mut raw=ptr::null_mut();ok(unsafe{(error.table::<Error>().replacement)(error.0,&mut raw)})?;let replacement=unsafe{string(raw)}?;let mut raw=ptr::null_mut();let word_wide=super::native::wide(&word);ok(unsafe{(checker.table::<Checker>().suggest)(checker.0,word_wide.as_ptr(),&mut raw)})?;let suggestions=strings(Com::new(raw)?,3)?;let finding=Finding{word,start:start as usize,length:length as usize,action,replacement,suggestions,context};let bytes=serde_json::to_vec(&finding).map_err(|e|e.to_string())?.len();if retained_bytes+bytes>512*1024{report.truncated=true;continue}retained_bytes+=bytes;report.findings.push(finding);
  }Ok(report)
 }
}
#[cfg(test)]mod tests{
 use super::*;
 #[test]fn unicode_ranges_and_validation(){let text:Vec<_>="😀 שלום qzx".encode_utf16().collect();assert_eq!(evidence(&text,3,4).unwrap().0,"שלום");assert_eq!(evidence(&text,8,3).unwrap().0,"qzx");assert!(evidence(&text,1,1).is_err());assert!(evidence(&text,10,2).is_err());assert!(check("a\0b","en-US").is_err());assert!(check(&"x".repeat(MAX_UNITS+1),"en-US").is_err());assert!(language("../bad").is_err())}
 #[cfg(windows)]#[test]fn installed_provider_checks_without_dictionary_writes(){let available=languages().unwrap();assert!(!available.is_empty());let tag=available.iter().find(|s|s.starts_with("en-")).expect("Acceptance host needs an English spelling provider");let good=check("Hello world",tag).unwrap();assert_eq!(good.total,0);let bad=check("😀 Hello qzxfitigspellprobe world",tag).unwrap();assert!(bad.findings.iter().any(|f|f.word=="qzxfitigspellprobe"));for f in bad.findings{let units:Vec<_>="😀 Hello qzxfitigspellprobe world".encode_utf16().collect();assert_eq!(String::from_utf16(&units[f.start..f.start+f.length]).unwrap(),f.word)}assert!(check("text","zz-ZZ").is_err())}
}
